    var sum_emb: F64 = 0.0
    for emb in token_embedding.values() do
      sum_emb = sum_emb + emb
    end
    potential = potential + sum_emb * 0.01 * F64.log(dim.f64() * grid_param.f64())
    quantum_phase = quantum_phase + F64.pi() / 180.0
  be kan_spline_eval(x: F64, coeffs: Array[F64] val, grid_param: USize) =>
    var knots = Array[F64].create(grid_param)
    for i in Range(0, grid_param) do
      knots.push(i.f64() / (grid_param.f64() - 1.0))
    end
    var basis = b_spline_basis(x, knots, 3)
  fun b_spline_basis(x: F64, knots: Array[F64] val, degree: USize): Array[F64] =>
