      var basis = Array[F64].create(prev_basis.size() - 1)
      for i in Range(0, prev_basis.size() - 1) do
        let term1 = if (knots(i + degree)? - knots(i)? != 0.0) then (x - knots(i)?) / (knots(i + degree)? - knots(i)?) * prev_basis(i)? else 0.0 end
        let term2 = if (knots(i + degree + 1)? - knots(i + 1)? != 0.0) then (knots(i + degree + 1)? - x) / (knots(i + degree + 1)? - knots(i + 1)?) * prev_basis(i + 1)? else 0.0 end
        basis.push(term1 + term2)
      end
      basis
    end
actor Main
