  }
  state.potential += sum_emb * 0.01 * math.log_f64(f64(DIM * grid))
  state.quantum_phase += math.PI / 180.0
  state.profile = "Updated"
}
kan_spline_eval :: proc(x: f64, coeffs: []f64, grid: int) -> f64 {
  knots := make([]f64, grid)
  defer delete(knots)
  for i in 0..<grid {
    knots[i] = f64(i) / f64(grid - 1)
  }
  basis := b_spline_basis(x, knots, 3)
  defer delete(basis)
  sum := 0.0
  for i in 0..<len(basis) {
    sum += basis[i] * coeffs[i]
  }
  return sum
