```gleam
import gleam/dynamic.{type Dynamic, Float, Int}
import gleam/string
import gleam/list
import gleam/float
import gleam/result
import gleam/bit_array
import gleam/json
import gleam/dict.{type Dict}
pub type Vocab {
  Vocab(mapping: Dict(String, Int), reverse: Dict(Int, String))
}
pub fn load_vocab(path: String) -> Vocab {
  let assert Ok(content) = bit_array.from_file(path)
  let assert Ok(decoded) = json.decode(content, dynamic.dict(dynamic.string, dynamic.int))
  let mapping = decoded
  let reverse = mapping
    |> dict.to_list
    |> list.map(fn(pair) { 
      let #(key, value) = pair
      #(value, key)
    })
    |> dict.from_list
  Vocab(mapping: mapping, reverse: reverse)
}
pub fn tokenize(vocab: Vocab, text: String) -> List(Int) {
  let normalized = normalize_text(text)
  normalized
  |> string.to_graphemes
  |> list.map(fn(grapheme) {
    dict.get(vocab.mapping, grapheme) |> result.unwrap(3)
  })
}
pub fn detokenize(vocab: Vocab, ids: List(Int)) -> String {
  ids
  |> list.map(fn(id) { dict.get(vocab.reverse, id) |> result.unwrap("?") })
  |> string.concat
}
fn normalize_text(text: String) -> String {
  text
  |> string.lowercase
  |> string.replace("-", " ")
  |> string.replace("  ", " ")
  |> string.trim
}
fn lorenz_embedding(id: Int, index: Int) -> List(Float) {
  let lorenz_params = [10.0, 28.0, 8.0 /. 3.0]
  let planet_index = index % 3
  let sigma = list.at(lorenz_params, planet_index) |> result.unwrap(10.0)
  let rho = list.at(lorenz_params, { planet_index + 1 } % 3) |> result.unwrap(28.0)
  let beta = list.at(lorenz_params, { planet_index + 2 } % 3) |> result.unwrap(8.0 /. 3.0)
  let dt = 0.01
  let x0 = int.to_float(id) *. 0.1
  let y0 = int.to_float(index) *. 2.0
  let z0 = 0.0
  let x1 = x0 +. dt *. {sigma *. {y0 -. x0}}
  let y1 = y0 +. dt *. {x0 *. {rho -. z0} -. y0}
  let z1 = z0 +. dt *. {x0 *. y0 -. beta *. z0}
  let phase = float.sin(x1) *. float.cos(y1) *. float.sin(z1)
  let sin_phase = float.sin(phase)
  let cos_phase = float.cos(phase)
  [phase, sin_phase, cos_phase, sigma, rho, beta, x1, y1, z1] 
  |> list.append(list.repeat(0.0, 9216 - 9))
}
fn b_spline_basis(x: Float, knots: List(Float), degree: Int) -> List(Float) {
  case degree {
    0 -> {
      knots 
      |> list.index_map(fn(i, k) { 
        case x >=. k && x <. {list.at(knots, i + 1) |> result.unwrap(k +. 1.0)} {
          True -> 1.0
          False -> 0.0
        }
      })
    }
    _ -> {
      let prev_basis = b_spline_basis(x, knots, degree - 1)
      prev_basis 
      |> list.index_map(fn(i, b) { 
        let k_i = list.at(knots, i) |> result.unwrap(0.0)
        let k_ipd = list.at(knots, i + degree) |> result.unwrap(1.0)
        let term1 = case k_ipd -. k_i != 0.0 {
          True -> {x -. k_i} /. {k_ipd -. k_i} *. b
          False -> 0.0
        }
        let next_b = list.at(prev_basis, i + 1) |> result.unwrap(0.0)
        let k_ip1 = list.at(knots, i + 1) |> result.unwrap(0.0)
        let k_ipd1 = list.at(knots, i + degree + 1) |> result.unwrap(1.0)
        let term2 = case k_ipd1 -. k_ip1 != 0.0 {
          True -> {k_ipd1 -. x} /. {k_ipd1 -. k_ip1} *. next_b
          False -> 0.0
        }
        term1 +. term2
      })
    }
  }
}
fn kan_spline_eval(x: Float, coeffs: List(Float), grid: Int) -> Float {
  let knots = list.range(0, grid) |> list.map(fn(i) { int.to_float(i) /. int.to_float(grid - 1) })
  let basis = b_spline_basis(x, knots, 3)
  list.zip(basis, coeffs) 
  |> list.map(fn(pair) { let #(b, c) = pair; b *. c }) 
  |> list.fold(0.0, float.add)
}
pub fn hybrid_tokenize(vocab: Vocab, text: String, grid: Int, birth_degrees: List(Float)) -> List(Token) {
  let normalized = normalize_text(text)
  normalized
  |> string.to_graphemes
  |> list.index_map(fn(index, grapheme) {
    let id = dict.get(vocab.mapping, grapheme) |> result.unwrap(0)
    let lorenz_emb = lorenz_embedding(id, index)
    let planet_index = index % list.length(birth_degrees)
    let degree = list.at(birth_degrees, planet_index) |> result.unwrap(0.0)
    let phase_shift = float.sin(int.to_float(index) *. 0.1 +. degree)
    let lorenz_emb_shifted = list.map(lorenz_emb, fn(val) { val +. phase_shift })
    let spline_x = int.to_float(index) /. int.to_float(string.length(text))
    let coeffs = list.repeat(1.0, grid)
    let spline_val = kan_spline_eval(spline_x, coeffs, grid)
    let embedding = list.map(lorenz_emb_shifted, fn(val) { val +. spline_val *. 0.01 })
    Token(id: id, embedding: embedding)
  })
}
pub type Token {
  Token(id: Int, embedding: List(Float))
}
