module Parallel {
  config const size = 16384;
  config const time_dim = 1024;
  proc kan_tgn_update(nodes: [0..size-1] real, memory: [0..size-1] real, time_factor: real, grid: int): [0..size-1] real {
    var updated: [0..size-1] real;
    forall i in 0..size-1 do {
      var spline_x = i: real / size: real;
      var coeffs: [0..grid-1] real = [j in 0..grid-1] 1.0;
      var spline_val = kan_spline_eval(spline_x, coeffs, grid);
      updated[i] = memory[i] * (1.0 - time_factor) + nodes[i] * time_factor + spline_val * 0.01;
    }
    return updated;
  }
  proc kan_spline_eval(x: real, coeffs: [?D] real, grid: int): real {
    var knots: [0..grid-1] real = [i in 0..grid-1] i: real / (grid - 1): real;
    var basis = b_spline_basis(x, knots, 3);
    var sum: real = 0.0;
    forall i in basis.domain with (+ reduce sum) do {
      sum += basis[i] * coeffs[i];
    }
    return sum;
  }
