  let sumEmb = List.sum token.embedding
  let pi = 3.141592653589793
  let newPotential = state.potential + sumEmb * 0.01 * Float.log (9216.0 * Nat.toFloat grid)
  let newPhase = state.quantum_phase + pi / 180.0
  let now = !realtime.now
  let profile = "Timestamp: " ++ Instant.toText now
  KANState.KANState newPotential newPhase (Instant.toEpochSeconds now |> Nat.toFloat) profile grid
