package kan_mamba2;
const DIM: i32 = 18432;
const GRID: i32 = 5;
fn LorenzEmbed(id: i32, index: i32) -> Array(f64) {
  var sigma: f64 = 10.0;
  var rho: f64 = 28.0;
  var beta: f64 = 8.0 / 3.0;
  var dt: f64 = 0.01;
  var x0: f64 = id as f64 * 0.1;
  var y0: f64 = index as f64 * 2.0;
  var z0: f64 = 0.0;
  var x1: f64 = x0 + dt * (sigma * (y0 - x0));
  var y1: f64 = y0 + dt * (x0 * (rho - z0) - y0);
  var z1: f64 = z0 + dt * (x0 * y0 - beta * z0);
  var phase: f64 = Math.Sin(x1) * Math.Cos(y1) * Math.Sin(z1);
  var sin_phase: f64 = Math.Sin(phase);
  var cos_phase: f64 = Math.Cos(phase);
  var base: Array(f64) = [phase, sin_phase, cos_phase, sigma, rho, beta, x1, y1, z1];
  var padding: Array(f64) = Array(f64).Repeat(0.0, DIM - 9);
  return base.Concat(padding);
}
fn BSplineBasis(x: f64, knots: Array(f64), degree: i32) -> Array(f64) {
  if (degree == 0) {
    var basis: Array(f64) = Array(f64).Empty();
    for (var i: i32 = 0; i < knots.Size() - 1; ++i) {
      if (x >= knots[i] && x < knots[i + 1]) {
        basis.Append(1.0);
      } else {
        basis.Append(0.0);
      }
    }
    return basis;
  } else {
    var prev_basis: Array(f64) = BSplineBasis(x, knots, degree - 1);
    var basis: Array(f64) = Array(f64).Empty();
    for (var i: i32 = 0; i < prev_basis.Size() - 1; ++i) {
      var term1: f64 = 0.0;
      if (knots[i + degree] - knots[i] != 0.0) {
        term1 = (x - knots[i]) / (knots[i + degree] - knots[i]) * prev_basis[i];
      }
      var term2: f64 = 0.0;
      if (knots[i + degree + 1] - knots[i + 1] != 0.0) {
        term2 = (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) * prev_basis[i + 1];
      }
      basis.Append(term1 + term2);
    }
    return basis;
  }
}
fn KanSplineEval(x: f64, coeffs: Array(f64), grid: i32) -> f64 {
  var knots: Array(f64) = Array(f64).Empty();
  for (var i: i32 = 0; i < grid; ++i) {
    knots.Append((i as f64) / ((grid - 1) as f64));
  }
  var basis: Array(f64) = BSplineBasis(x, knots, 3);
  var sum: f64 = 0.0;
  for (var i: i32 = 0; i < basis.Size(); ++i) {
    sum += basis[i] * coeffs[i];
  }
  return sum;
}
fn HybridTokenize(text: String, grid: i32, birth: Array(f64)) -> Array(Token) {
  var norm: String = text.ToLower().Replace("-", " ").Replace("  ", " ").Trim();
  var tokens: Array(Token) = Array(Token).Empty();
  for (var index: i32 = 0; index < norm.Size(); ++index) {
    var id: i32 = norm[index] as i32;
    var lorenz: Array(f64) = LorenzEmbed(id, index);
    var degree: f64 = birth[index % birth.Size()];
    var phase_shift: f64 = Math.Sin((index as f64) * 0.1 + degree);
    var lorenz_shift: Array(f64) = Array(f64).Empty();
    for (var j: i32 = 0; j < lorenz.Size(); ++j) {
      lorenz_shift.Append(lorenz[j] + phase_shift);
    }
    var spline_x: f64 = (index as f64) / (text.Size() as f64);
    var coeffs: Array(f64) = Array(f64).Repeat(1.0, grid);
    var spline_val: f64 = KanSplineEval(spline_x, coeffs, grid);
    var emb: Array(f64) = Array(f64).Empty();
    for (var j: i32 = 0; j < lorenz_shift.Size(); ++j) {
      emb.Append(lorenz_shift[j] + spline_val * 0.01);
    }
    tokens.Append(Token{id: id, embedding: emb});
  }
  return tokens;
