        term2 = (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) * prevBasis[i + 1]
      result[i] = term1 + term2
proc kanSplineEval(x: float, coeffs: seq[float], grid: int): float =
  var knots = newSeq[float](grid)
