function lorenz_embed(id::Int, index::Int)
  sigma = 10.0
  rho = 28.0
  beta = 8.0 / 3.0
  dt = 0.01
  x0 = Float64(id) * 0.1
  y0 = Float64(index) * 2.0
  z0 = 0.0
  x1 = x0 + dt * (sigma * (y0 - x0))
  y1 = y0 + dt * (x0 * (rho - z0) - y0)
  z1 = z0 + dt * (x0 * y0 - beta * z0)
  phase = sin(x1) * cos(y1) * sin(z1)
  sin_phase = sin(phase)
  cos_phase = cos(phase)
  vcat([phase, sin_phase, cos_phase, sigma, rho, beta, x1, y1, z1], zeros(Float64, DIM - 9))
end
function b_spline_basis(x::Float64, knots::Vector{Float64}, degree::Int)
  if degree == 0
    [ (x >= knots[i] && x < knots[i+1]) ? 1.0 : 0.0 for i in 1:(length(knots)-1) ]
  else
    prev_basis = b_spline_basis(x, knots, degree - 1)
    [ 
      ((knots[i + degree] - knots[i] != 0.0) ? (x - knots[i]) / (knots[i + degree] - knots[i]) * prev_basis[i] : 0.0) +
      ((knots[i + degree + 1] - knots[i + 1] != 0.0) ? (knots[i + degree + 1] - x) / (knots[i + degree + 1] - knots[i + 1]) * prev_basis[i + 1] : 0.0)
      for i in 1:(length(prev_basis) - 1)
    ]
  end
end
function kan_spline_eval(x::Float64, coeffs::Vector{Float64}, grid::Int)
  knots = [ Float64(i) / Float64(grid - 1) for i in 0:(grid-1) ]
  basis = b_spline_basis(x, knots, 3)
  sum(basis .* coeffs)
end
