      degree = birth[((i - 1) % length(birth)) + 1]
      phase_shift = sin((i - 1) * 0.1 + degree)
      lorenz_shift = lorenz .+ phase_shift
      spline_x = (i - 1) / length(text)
      coeffs = ones(Float64, grid)
      spline_val = kan_spline_eval(spline_x, coeffs, grid)
      emb = lorenz_shift .+ (spline_val * 0.01)
      Token(id, emb)
    end for i in 1:length(norm) ]
end
